declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require dirname(__DIR__,2).'/app/services/AnalyticsService.php';$u=require_auth();$q=db()->prepare('SELECT id,name FROM trading_systems WHERE user_id=? ORDER BY name');$q->execute([$u['id']]);$systems=$q->fetchAll();$analytics=(new \App\Services\AnalyticsService())->build(db(),(int)$u['id'],[]);$rows=$analytics['by_system'];$best=$rows[0]??null;$worst=$rows?$rows[count($rows)-1]:null;$avgR=[];foreach($analytics['trades'] as $t)if($t['risk']['expected_r']!==null)$avgR[]=(float)$t['risk']['expected_r'];$ev=$avgR?array_sum($avgR)/count($avgR):null;$quality=$analytics['summary']['count']?100*$analytics['summary']['wins']/$analytics['summary']['count']:0;render('system_report',['title'=>'System Report','analytics'=>$analytics,'rows'=>$rows,'best'=>$best,'worst'=>$worst,'ev'=>$ev,'quality'=>$quality]);
